@triton.jit
def min_kernel(output_ptr, input_ptr, input_row_stride, output_row_stride, n_rows, n_cols, BLOCK_SIZE: tl.constexpr):
    row_idx = tl.program_id(0)
    row_start_ptr = input_ptr + row_idx * input_row_stride
    col_offsets = tl.arange(0, BLOCK_SIZE)
    mask = col_offsets < n_cols
    row = tl.load(row_start_ptr + col_offsets, mask=mask, other=float('inf'))
    row_min = tl.min(row, axis=0)
    tl.store(output_ptr + row_idx, row_min)

def min(input_tensor, dim, keepdim=False, *, out=None):
    if input_tensor.dim() == 1:
        input_tensor = input_tensor.unsqueeze(0)
    n_rows, n_cols = input_tensor.shape
    BLOCK_SIZE = triton.next_power_of_2(n_cols)
    if keepdim:
        output_shape = (n_rows, 1) if dim == 0 else (1, n_cols)
    else:
        output_shape = (n_rows,)
    output = torch.empty(*output_shape, device=input_tensor.device, dtype=input_tensor.dtype)
    min_kernel[(n_rows,)](output, input_tensor, input_tensor.stride(0), output.stride(0), n_rows, n_cols, BLOCK_SIZE=BLOCK_SIZE)
    if keepdim:
        return output.squeeze(dim)
    else:
        return output
